// Phase 4 #5 — `harness policy intercept` CLI entrypoint.
//
// Wired by Claude Code's settings.json (regenerated by `harness apply`) as
// the PreToolUse hook. Reads the event JSON from stdin, runs the runtime
// interceptor, writes Claude Code's deny JSON to stdout on block.

import {
  queryLedgerByTag,
  type LedgerEntry,
  type LedgerQueryResult,
} from "../../policies/index.js";
import * as fs from "node:fs";
import * as os from "node:os";
import {
  intercept,
  recordPolicyDecision,
  resolveGitContext,
  resolveKubeContext,
  type LedgerClient,
  type PolicyDecision,
  type RiskGateContext,
  type ToolEvent,
} from "../../runtime/index.js";
import type { Manifest, McpServer } from "../../schema/index.js";
import { resolveGeneratedDir, writePendingApproval } from "../../runtime/pending-approval.js";
import { loadManifest, type LoaderOptions } from "../loader.js";
import { checkPauseFromLoader } from "../pause-check.js";

export interface InterceptCliOptions extends LoaderOptions {
  /** Defaults to process.stdin. */
  stdin?: NodeJS.ReadableStream;
  /** Defaults to process.stdout. */
  stdout?: NodeJS.WritableStream;
  /** Defaults to process.stderr. */
  stderr?: NodeJS.WritableStream;
  /** Override timeout per ledger call. */
  ledgerTimeoutMs?: number;
  /** Override "now" for deterministic tests. */
  now?: Date;
  /** Inject a fake ledger client (tests). */
  ledger?: LedgerClient;
  /** Inject the resolved manifest (tests). */
  manifest?: Manifest;
  /**
   * Test-injected generatedDir for the pause-sentinel lookup; bypasses
   * path resolution when supplied. Mirrors the pack hooks' option.
   */
  generatedDir?: string;
  /**
   * When true (or `HARNESS_POLICY_VERBOSE` env is truthy), emit a
   * human-readable diagnostic block to stderr for each non-allow
   * decision. stdout is unaffected, so Claude Code's deny JSON contract
   * is preserved. Phase 5 #3 — opt-in only.
   */
  verbose?: boolean;
  /**
   * Risk Gate seams (Phase 7 #5). Override the ambient inputs the
   * Context Resolver matches `environments.resolvers[]` signals
   * against, so a test exercising a `when:` policy stays hermetic.
   * `env` defaults to `process.env`; the kube seams bypass the
   * `~/.kube/config` read when either is supplied.
   */
  env?: Record<string, string | undefined>;
  kubeContext?: string;
  kubeNamespace?: string;
  /**
   * Test seam for Codex's sandbox `--command-cwd` process argument.
   * Production resolves it from `/proc/1/cmdline` when Codex does not
   * include a cwd/workdir in the hook event payload.
   */
  codexCommandCwd?: string;
  /**
   * Name of the manifest hook that fired this intercept invocation. Set
   * by the Codex generator (`generate-codex-config.ts`) as the argv flag
   * `--hook <name>` so every spawned process self-identifies. Used as a
   * stderr-line prefix and a tag in the no-match hint; when absent the
   * existing back-compat behaviour (un-tagged stderr) holds. Codex emits
   * one `[[hooks.*]]` block per manifest hook so the per-hook tag is
   * unambiguous; the Claude Code generator dedupes by `(command, timeout)`
   * within a matcher group, so this flag is NOT injected there (it would
   * defeat the dedupe and N-multiply audit-writes per tool event).
   */
  hookName?: string;
}

export interface InterceptCliResult {
  exitCode: number;
  decisions: PolicyDecision[];
  blocked: boolean;
}

async function readStdin(stream: NodeJS.ReadableStream): Promise<string> {
  return new Promise((resolve, reject) => {
    let data = "";
    stream.setEncoding("utf8");
    stream.on("data", (chunk: string) => {
      data += chunk;
    });
    stream.on("end", () => resolve(data));
    stream.on("error", (err) => reject(err));
  });
}

function findGroundingMcp(manifest: Manifest): McpServer | null {
  return manifest.tools.mcp.find((m) => m.name === "grounding-mcp") ?? null;
}

/** Resolve an `os` fact, returning "" on the (rare) lookup failure. */
function safeOs(fn: () => string): string {
  try {
    return fn();
  } catch {
    return "";
  }
}

/**
 * Render the hook-identity suffix for a stderr diagnostic. Returns the
 * empty string when no `--hook` flag was supplied, so an operator
 * invoking `harness policy intercept` by hand (and tests that don't
 * inject hookName) see the original prefix verbatim.
 */
function hookSuffix(hookName: string | undefined): string {
  return hookName !== undefined && hookName.length > 0 ? ` [hook=${hookName}]` : "";
}

/**
 * Phase 5 #3 — render a deny / warn-degraded decision as a stderr
 * diagnostic block. Multiline, indented; each block is bounded by the
 * policy name so concurrent fires (rare but possible) stay readable.
 */
function formatDecisionDiagnostic(decision: PolicyDecision, hookName?: string): string {
  const header = `harness policy intercept${hookSuffix(hookName)}: ${decision.policyName}: ${decision.outcome}${
    decision.outcome === "warn-degraded" ? " (ledger unreachable)" : ""
  }`;
  const lines: string[] = [header];
  lines.push(`  ledger_tag: ${decision.ledgerTag}`);
  if (decision.requiresEval !== undefined) {
    lines.push(`  matched: ${decision.requiresEval.matchedCount}`);
  }
  lines.push(`  reason: ${decision.reason}`);
  const extractKeys = Object.keys(decision.extractValues);
  if (extractKeys.length > 0) {
    lines.push("  extract:");
    for (const k of extractKeys.sort()) {
      lines.push(`    ${k}=${decision.extractValues[k]}`);
    }
  }
  return `${lines.join("\n")}\n`;
}

function isVerboseEnabled(opts: InterceptCliOptions): boolean {
  if (opts.verbose === true) return true;
  if (opts.verbose === false) return false;
  const env = process.env.HARNESS_POLICY_VERBOSE;
  if (typeof env !== "string") return false;
  if (env.length === 0) return false;
  // Accept anything truthy except literal disable-words (case-insensitive).
  return !/^(0|false|no|off)$/i.test(env.trim());
}

function isCodexShellTool(toolName: unknown): boolean {
  return (
    toolName === "Bash" ||
    toolName === "shell" ||
    toolName === "exec_command" ||
    toolName === "functions.exec_command"
  );
}

function extractPerCallCwd(input: unknown): string | null {
  if (!input || typeof input !== "object" || Array.isArray(input)) return null;
  const args = input as { cwd?: unknown; workdir?: unknown };
  for (const candidate of [args.workdir, args.cwd]) {
    if (typeof candidate === "string" && candidate.length > 0) return candidate;
  }
  return null;
}

function readCodexCommandCwdFromProc(): string | null {
  let argv: string[];
  try {
    argv = fs.readFileSync("/proc/1/cmdline", "utf8").split("\0");
  } catch {
    return null;
  }
  const idx = argv.indexOf("--command-cwd");
  const cwd = idx >= 0 ? argv[idx + 1] : undefined;
  return typeof cwd === "string" && cwd.length > 0 ? cwd : null;
}

function resolvePolicyCwd(event: ToolEvent, codexCommandCwd?: string): string {
  if (typeof event.cwd === "string" && event.cwd.length > 0) return event.cwd;
  if (isCodexShellTool(event.tool_name)) {
    for (const input of [event.raw_input, event.tool_input, event.input]) {
      const cwd = extractPerCallCwd(input);
      if (cwd) return cwd;
    }
    if (codexCommandCwd !== undefined && codexCommandCwd.length > 0) {
      return codexCommandCwd;
    }
    const procCwd = readCodexCommandCwdFromProc();
    if (procCwd) return procCwd;
  }
  return process.cwd();
}

/**
 * Real grounding-mcp-backed ledger client. Exported for testing: the
 * `record` adapter's failure-surfacing path is exercised against a
 * bogus mcpCommand in tests/runtime/intercept-cli.test.ts.
 */
export function realLedgerClient(
  server: McpServer,
  opts: InterceptCliOptions,
): LedgerClient {
  const command = Array.isArray(server.command)
    ? server.command
    : server.command.trim().split(/\s+/);
  const env = server.env ?? undefined;
  const timeoutMs = opts.ledgerTimeoutMs ?? server.health?.timeout_ms ?? 5_000;
  const stderr = opts.stderr ?? process.stderr;
  return {
    async query(_tag, sessionId): Promise<LedgerQueryResult> {
      return queryLedgerByTag({
        mcpCommand: command,
        ...(env && { mcpEnv: env }),
        sessionId,
        timeoutMs,
      });
    },
    async record(decision, sessionId): Promise<void> {
      const result = await recordPolicyDecision(decision, sessionId, {
        mcpCommand: command,
        ...(env && { mcpEnv: env }),
        timeoutMs,
      });
      // A failed audit-write must not block the tool — the decision is
      // still applied — but it must not be silent either: an unrecorded
      // decision is invisible to `harness audit` / `explain --trace`.
      // Goes to stderr so Claude Code's stdout deny-JSON contract holds.
      if (!result.ok) {
        stderr.write(
          `harness policy intercept${hookSuffix(opts.hookName)}: audit-write failed for ` +
            `${decision.policyName}: ${result.reason ?? "unknown error"}\n`,
        );
      }
    },
  };
}

function degradedLedgerClient(reason: string): LedgerClient {
  return {
    async query(): Promise<LedgerQueryResult> {
      return { kind: "degraded", reason };
    },
    async record(): Promise<void> {
      /* no-op when ledger is unavailable */
    },
  };
}

export async function runInterceptCli(
  opts: InterceptCliOptions = {},
): Promise<InterceptCliResult> {
  const stdin = opts.stdin ?? process.stdin;
  const stdout = opts.stdout ?? process.stdout;
  const stderr = opts.stderr ?? process.stderr;
  const verbose = isVerboseEnabled(opts);
  const raw = await readStdin(stdin);
  let event: ToolEvent;
  try {
    event = JSON.parse(raw.trim() || "{}") as ToolEvent;
  } catch (err) {
    stderr.write(
      `harness policy intercept${hookSuffix(opts.hookName)}: malformed event JSON: ${(err as Error).message}\n`,
    );
    return { exitCode: 0, decisions: [], blocked: false };
  }

  // Pause sentinel — operator-only kill switch. Honoured BEFORE manifest
  // load so the lockout-recovery flow (where the manifest is exactly what
  // is broken) still respects an active pause. Mirrors the pack PreToolUse
  // hook: without this the policy gates kept firing while paused, i.e. the
  // very gates the kill switch most needs to silence (a wedged preflight /
  // grounding gate is the canonical reason an operator pauses at all).
  {
    const pauseOpts: Parameters<typeof checkPauseFromLoader>[0] = {
      loaderOpts: opts,
      hookLabel: "policy intercept",
      stderr,
    };
    if (opts.generatedDir !== undefined) pauseOpts.generatedDir = opts.generatedDir;
    if (opts.now !== undefined) pauseOpts.now = opts.now;
    if (checkPauseFromLoader(pauseOpts).paused) {
      return { exitCode: 0, decisions: [], blocked: false };
    }
  }

  let manifest: Manifest;
  let manifestPath: string | undefined;
  try {
    if (opts.manifest) {
      manifest = opts.manifest;
    } else {
      const loaded = loadManifest(opts);
      manifest = loaded.manifest;
      manifestPath = loaded.resolved.base;
    }
  } catch (err) {
    stderr.write(
      `harness policy intercept${hookSuffix(opts.hookName)}: manifest load failed: ${(err as Error).message}\n`,
    );
    return { exitCode: 0, decisions: [], blocked: false };
  }

  let ledger: LedgerClient;
  if (opts.ledger) {
    ledger = opts.ledger;
  } else {
    const server = findGroundingMcp(manifest);
    ledger = server
      ? realLedgerClient(server, opts)
      : degradedLedgerClient("grounding-mcp not declared in manifest");
  }

  // For the SESSION_ID builtin we keep the empty-string fallback rather
  // than routing through resolveSessionId (which lands on "default").
  // Routing through "default" would silently bake the literal string
  // into ledger_tag templates like `dogfood:${SESSION_ID}` →
  // `dogfood:default`, which would substring-match anything in the
  // shared "default" session — a worse failure mode than the current
  // empty substitution. The empty path produces tags like `dogfood:`
  // (substituteTemplate treats the registered "" value as a successful
  // substitution since the key is hasOwnProperty-present, so this is
  // NOT marked warn-degraded by the requires evaluator); the ledger
  // query for that fire also lands on the resolveSessionId-derived
  // session, so the asymmetry is acceptable in practice. Do NOT
  // "simplify" by routing this through resolveSessionId.
  // The env fallback is still applied so a Claude-Code-driven hook with
  // a stripped event can pick up the active session.
  const eventSessionId = typeof event.session_id === "string" ? event.session_id : undefined;
  const builtinSessionId = eventSessionId ?? process.env.CLAUDE_SESSION_ID ?? "";
  // REPO / BRANCH are derived from the tool event's cwd so that per-repo
  // and per-branch ledger tags (`preflight:${REPO}`, `preflight:${BRANCH}`)
  // actually namespace — they were previously read from HARNESS_REPO /
  // HARNESS_BRANCH env vars that nothing sets, collapsing every tag to the
  // literal `preflight:`. An explicit env var still wins: it is the
  // operator's deliberate override of the derived value.
  const cwd = resolvePolicyCwd(event, opts.codexCommandCwd);
  const gitContext = resolveGitContext(cwd);
  const builtins = {
    SESSION_ID: builtinSessionId,
    REPO: process.env.HARNESS_REPO ?? gitContext.repo,
    BRANCH: process.env.HARNESS_BRANCH ?? gitContext.branch,
    TOOL_NAME: typeof event.tool_name === "string" ? event.tool_name : "",
    CWD: cwd,
  };

  // Risk Gate ambient context — resolved only when the manifest
  // declares a `when:`-bearing policy, so a pure Phase-4 manifest pays
  // no kube-config read. `intercept()` applies the same gate; this just
  // avoids the host I/O when nothing would consume it.
  let riskContext: RiskGateContext | undefined;
  if (manifest.policies.some((p) => p.when !== undefined)) {
    const kube =
      opts.kubeContext !== undefined || opts.kubeNamespace !== undefined
        ? {
            context: opts.kubeContext ?? "",
            namespace: opts.kubeNamespace ?? "",
          }
        : resolveKubeContext();
    riskContext = {
      git: gitContext,
      cwd,
      user: safeOs(() => os.userInfo().username),
      host: safeOs(() => os.hostname()),
      env: opts.env ?? process.env,
      kubeContext: kube.context,
      kubeNamespace: kube.namespace,
    };
  }

  const result = await intercept({
    manifest,
    event,
    ledger,
    builtins,
    ...(opts.ledgerTimeoutMs !== undefined && { ledgerTimeoutMs: opts.ledgerTimeoutMs }),
    ...(opts.now && { now: opts.now }),
    ...(gitContext.sha.length > 0 && { currentHeadSha: gitContext.sha }),
    ...(riskContext && { riskContext }),
  });

  // Stage the session id for a later arg-less `harness approve risk`
  // whenever the FIRST blocking decision is `require_approval`. Mirrors
  // the Understanding Gate hook (src/cli/pack/hook-pre-tool-use.ts):
  // the producer side knows the live session id (it just received it on
  // the hook event), but `harness approve risk` runs from the operator's
  // `!`-shell where `$CLAUDE_SESSION_ID` is unset, so it has to read the
  // marker. `deny` decisions are deliberately not staged: `harness approve
  // risk` cannot unblock a `deny`, and writing a marker the verb cannot
  // act on would just lie about the recoverability of the block. The
  // "first blocking decision" check (rather than `.some()`) matters when
  // two `when:`-bearing policies fire on the same event: the runtime's
  // `intercept()` picks the first blocking decision (`runtime/intercept.ts:511`),
  // so a `deny`-first / `require_approval`-second order produces an
  // unrecoverable block; we mustn't stage in that case either.
  //
  // Best-effort: a staging-write failure must never escalate a gate block
  // into a thrown hook error. `resolveGeneratedDir` is skipped (along
  // with the write) when no manifest path could be resolved — tests
  // exercise the policy logic with injected manifests and no on-disk
  // path, and the test path is also the only place an empty
  // `eventSessionId` is interesting.
  const firstBlocking = result.decisions.find(
    (d) =>
      (d.outcome === "deny" && d.enforcement === "block") ||
      d.outcome === "require_approval",
  );
  if (
    result.blockJson &&
    eventSessionId !== undefined &&
    eventSessionId.length > 0 &&
    firstBlocking?.outcome === "require_approval"
  ) {
    const generatedDir = opts.generatedDir
      ?? (manifestPath !== undefined
        ? resolveGeneratedDir({
            ...(opts.homeDir !== undefined ? { homeDir: opts.homeDir } : {}),
            manifestPath,
          })
        : undefined);
    if (generatedDir !== undefined) {
      try {
        writePendingApproval(generatedDir, eventSessionId);
      } catch {
        /* best-effort; the block below proceeds regardless */
      }
    }
  }

  if (result.blockJson) {
    stdout.write(`${JSON.stringify(result.blockJson)}\n`);
  }

  // No-match diagnostic. Always (not gated on --verbose) when the
  // manifest has at least one policy but none of them matched this
  // event. Catches the common debug footgun where an operator probes
  // `harness policy intercept` by hand and forgets `hook_event_name`,
  // making the engine return exit 0 + empty stdout. The probe then
  // looks like "policy did not load", when in fact the trigger filter
  // simply rejected the input. Emits to stderr so the Claude Code
  // hook contract on stdout is preserved.
  if (result.decisions.length === 0 && manifest.policies.length > 0) {
    stderr.write(formatNoMatchHint(event, manifest, opts.hookName));
  }

  if (verbose) {
    for (const decision of result.decisions) {
      if (decision.outcome === "allow") continue;
      stderr.write(formatDecisionDiagnostic(decision, opts.hookName));
    }
  }

  return {
    exitCode: 0,
    decisions: result.decisions,
    blocked: result.blockJson !== null,
  };
}

function formatNoMatchHint(event: ToolEvent, manifest: Manifest, hookName?: string): string {
  const observedEvent =
    typeof event.hook_event_name === "string" && event.hook_event_name.length > 0
      ? `"${event.hook_event_name}"`
      : "(missing)";
  const observedTool =
    typeof event.tool_name === "string" && event.tool_name.length > 0
      ? `"${event.tool_name}"`
      : "(missing)";
  const registeredEvents = Array.from(
    new Set(manifest.policies.map((p) => p.trigger.event)),
  ).sort();
  return (
    `harness policy intercept${hookSuffix(hookName)}: no policy matched event ` +
    `hook_event_name=${observedEvent} tool_name=${observedTool} ` +
    `(registered policy events: ${registeredEvents.join(", ")}). ` +
    `If probing by hand, ensure stdin includes hook_event_name (e.g. "PreToolUse" for tool gates).\n`
  );
}

export type { LedgerEntry };
